INSERT OR IGNORE INTO loras (id, name, kind, filename, hf_url, trigger_words, default_strength, steps_hint, workflows_json, notes, created_at, updated_at) VALUES
  ('lora_fal_realism_people', 'fal Realism People v2', 'style', 'fal_h3_realism_people.safetensors',
   'https://huggingface.co/fal/MiniMax-H3-Realism-People-LoRA',
   'r34l1sm', 0.8, NULL, '[]', 'fal''s people-focused realism LoRA (rank 32, 1500 steps, hi-res): close-up faces, skin texture, natural expressions, documentary camera. Works on T2V / I2V / R2V. Start at 0.8; lower it when stacked on the turbo LoRA.', 1762400000000, 1762400000000),
  ('lora_jojocodex_camera', 'Jojocodex Camera Motion', 'effect', 'jojocodex_h3_camera_motion.safetensors',
   'https://huggingface.co/Jojocodex/minimax-h3-Camera-Motion-lora',
   '', 0.6, NULL, '["T2VA"]', 'Camera-move control (push-in, orbit, crane…) for text-to-video; the repo ships a camera-motion prompt library. The pod picks the 3000-step pruned file. Pair with the shot''s camera field; try 0.5–0.7.', 1762400000000, 1762400000000),
  ('lora_jojocodex_physics', 'Jojocodex Spatial Physics', 'effect', 'jojocodex_h3_spatial_physics.safetensors',
   'https://huggingface.co/Jojocodex/minimax-h3-spatial-physics-lora',
   '', 0.4, NULL, '[]', 'Object relationships and physical motion (collision, stacking, falling, occlusion). Author: still training, not fully stable, strength 0.3–0.5.', 1762400000000, 1762400000000),
  ('lora_prithiv_facial_closeup', 'prithivMLmods Facial Realism CloseUp', 'style', 'prithiv_h3_facial_realism_closeup.safetensors',
   'https://huggingface.co/prithivMLmods/MiniMax-H3-Facial-Realism-CloseUp',
   'Facial Realism', 0.6, NULL, '[]', 'Experimental face-realism adapter for close-ups; the author warns about artifacts. Per-shot only (cu / ecu), not a project default.', 1762400000000, 1762400000000),
  ('lora_prithiv_anime_motion', 'prithivMLmods I2V Anime Motion', 'style', 'prithiv_h3_i2v_anime_motion.safetensors',
   'https://huggingface.co/prithivMLmods/MiniMax-H3-I2V-Anime-Motion-LoRA',
   '', 0.8, NULL, '["I2VA","FL2VA"]', 'Anime motion for image-to-video: animates an anime still with genre-typical movement. Use with a hero frame.', 1762400000000, 1762400000000),
  ('lora_innerreflections_sketch_loop', 'Inner-Reflections Looping Sketch Anime', 'style', 'innerreflections_h3_looping_sketch_anime.safetensors',
   'https://huggingface.co/Inner-Reflections/MiniMax-H3-Looping-Sketch-Anime',
   '', 1.0, NULL, '[]', 'Hand-drawn anime sketch look that loops; model card suggests 0.75–1.25. Natural fit for the loop link + timeline repeat.', 1762400000000, 1762400000000),
  ('lora_diffsynth_lineart_anime', 'DiffSynth LineartAnime', 'effect', 'diffsynth_h3_lineart_anime.safetensors',
